  storeName: 'KasirKu',
  storeAddress: '',
  storePhone: '',
  storeNPWP: '',
  storeLogo: '', // base64 dataURL, dikompres client-side sama seperti foto produk
  invoiceCounters: {}, // { fnb: {date, seq}, retail: {date, seq}, all: {date, seq} } — nomor invoice resmi harian per tipe bisnis
