  currentShift: null, // { id, cashierName, openingCash, openedAt, closedAt, closingCashCounted, notes }
  shiftHistory: [], // 'pct' | 'nominal'
};

const COLORS = ['#D1FAE5','#FED7AA','#FDE68A','#E9D5FF','#FECDD3','#BFDBFE'];
let productColorMap = {};

// ============================================================
// NAVIGATION
// ============================================================
const MANAGER_ONLY_PAGES = ['keuangan', 'bahanbaku', 'laporan', 'pengaturan'];
let _managerAccessGranted = false; // reset tiap login baru — sekali PIN manajer benar, tidak ditanya lagi selama sesi ini
let _pendingManagerPage = null;

function navigate(page) {
  if (MANAGER_ONLY_PAGES.includes(page) && state.currentCashier?.role !== 'manajer' && !_managerAccessGranted) {
    _pendingManagerPage = page;
    document.getElementById('page-access-pin-input').value = '';
    document.getElementById('page-access-pin-error').classList.add('hidden');
    document.getElementById('page-access-pin-modal').classList.remove('hidden');
    setTimeout(() => document.getElementById('page-access-pin-input').focus(), 100);
    return;
  }
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
  document.getElementById(`page-${page}`).classList.add('active');
  document.querySelectorAll(`[data-page="${page}"]`).forEach(n => n.classList.add('active'));
  if (page === 'laporan') renderReport();
  if (page === 'keuangan') renderKeuangan();
  if (page === 'bahanbaku') renderBahanBakuPage();
  if (page === 'inventory') renderInventory();
  if (page === 'pengaturan') renderSettings();
  if (page === 'aktivitas') renderActivityLog();
  closeSheet();
}

function closePageAccessPin() {
  document.getElementById('page-access-pin-modal').classList.add('hidden');
  _pendingManagerPage = null;
}

function confirmPageAccessPin() {
  const pin = document.getElementById('page-access-pin-input').value.trim();
  const manajer = state.cashiers.find(c => c.role === 'manajer' && c.pin === pin);
  if (!manajer) {
    document.getElementById('page-access-pin-error').classList.remove('hidden');
    document.getElementById('page-access-pin-input').value = '';
    return;
  }
  _managerAccessGranted = true;
  addLog('sistem', 'info', `Akses halaman manajer dibuka: ${manajer.name}`, `Untuk kasir: ${state.currentCashier?.name || '-'}`);
  updateManagerLockBadges();
  document.getElementById('page-access-pin-modal').classList.add('hidden');
  const page = _pendingManagerPage;
  _pendingManagerPage = null;
  if (page) navigate(page);
}



// ============================================================
// PRODUCTS
// ============================================================
// Filter produk berdasarkan tipe bisnis aktif — F&B dan Retail tidak boleh saling nyampur item.
// Produk lama tanpa scope (dari sebelum fitur ini ada) dianggap 'all' supaya tidak hilang tiba-tiba.
// Produk yang dibuat SETELAH fitur ini ada otomatis tertandai scope sesuai mode aktif saat dibuat.
// Filter data (transaksi/pengeluaran/rekonsiliasi/dll) berdasarkan tipe bisnis aktif —
// prinsipnya sama dengan getScopedProducts(): F&B dan Retail dianggap 2 bisnis terpisah.
// Data lama tanpa tag businessType dianggap 'all' supaya tidak hilang tiba-tiba.
function filterByBusinessScope(items) {
  if (state.businessType === 'all') return items;
  return items.filter(item => (item.businessType || 'all') === 'all' || item.businessType === state.businessType);
}

function getScopedProducts() {
  if (state.businessType === 'all') return state.products;
  return state.products.filter(p => (p.scope || 'all') === 'all' || p.scope === state.businessType);
}

