              <button
                onClick={() => {
                  setPaying(false);
                  setError(null);
                }}
                className="w-full py-1 text-center text-xs font-medium text-zinc-400 hover:text-zinc-600"
              >
                Batal
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

