1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { checkout } from "./actions";
6	import SwitchCashierButton from "./switch-cashier-button";
7	
8	type Product = {
9	  id: string;
10	  name: string;
11	  category: string | null;
12	  price: number;
13	  cost: number;
14	  stock: number;
15	  emoji: string | null;
16	};
17	
18	type CartItem = {
19	  productId: string;
20	  name: string;
21	  price: number;
22	  qty: number;
23	  maxStock: number;
24	};
25	
26	const PAYMENT_METHODS = ["Tunai", "Kartu", "QRIS"];
27	
28	function formatRupiah(value: number) {
29	  return `Rp${value.toLocaleString("id-ID")}`;
30	}
31	
32	export default function PosScreen({
33	  businessId,
34	  businessName,
35	  cashierId,
36	  cashierName,
37	  products,
38	}: {
39	  businessId: string;
40	  businessName: string;
41	  cashierId: string;
42	  cashierName: string;
43	  products: Product[];
44	}) {
45	  const router = useRouter();
46	  const [search, setSearch] = useState("");
47	  const [cart, setCart] = useState<CartItem[]>([]);
48	  const [paying, setPaying] = useState(false);
49	  const [paymentMethod, setPaymentMethod] = useState(PAYMENT_METHODS[0]);
50	  const [received, setReceived] = useState("");
51	  const [submitting, setSubmitting] = useState(false);
52	  const [error, setError] = useState<string | null>(null);
53	  const [successInvoice, setSuccessInvoice] = useState<string | null>(null);
54	
55	  const filteredProducts = useMemo(() => {
56	    const q = search.trim().toLowerCase();
57	    if (!q) return products;
58	    return products.filter((p) => p.name.toLowerCase().includes(q));
59	  }, [search, products]);
60	
61	  const subtotal = cart.reduce((sum, item) => sum + item.price * item.qty, 0);
62	  const receivedAmount = Number(received) || 0;
63	  const change = paymentMethod === "Tunai" ? receivedAmount - subtotal : 0;
64	
65	  function addToCart(product: Product) {
66	    setCart((prev) => {
67	      const existing = prev.find((i) => i.productId === product.id);
68	      if (existing) {
69	        if (existing.qty >= product.stock) return prev;
70	        return prev.map((i) =>
71	          i.productId === product.id ? { ...i, qty: i.qty + 1 } : i,
72	        );
73	      }
74	      if (product.stock <= 0) return prev;
75	      return [
76	        ...prev,
77	        { productId: product.id, name: product.name, price: product.price, qty: 1, maxStock: product.stock },
78	      ];
79	    });
80	  }
81	
82	  function changeQty(productId: string, delta: number) {
83	    setCart((prev) =>
84	      prev
85	        .map((i) =>
86	          i.productId === productId
87	            ? { ...i, qty: Math.min(i.maxStock, Math.max(0, i.qty + delta)) }
88	            : i,
89	        )
90	        .filter((i) => i.qty > 0),
91	    );
92	  }
93	
94	  function removeFromCart(productId: string) {
95	    setCart((prev) => prev.filter((i) => i.productId !== productId));
96	  }
97	
98	  async function handleConfirmPayment() {
99	    setError(null);
100	
101	    if (paymentMethod === "Tunai" && receivedAmount < subtotal) {
102	      setError("Uang diterima kurang dari total belanja.");
103	      return;
104	    }
105	
106	    setSubmitting(true);
107	    const result = await checkout(
108	      businessId,
109	      cashierId,
110	      cart.map((i) => ({ productId: i.productId, qty: i.qty })),
111	      paymentMethod,
112	      paymentMethod === "Tunai" ? receivedAmount : subtotal,
113	    );
114	    setSubmitting(false);
115	
116	    if (!result.success) {
117	      setError(result.error);
118	      return;
119	    }
120	
121	    setSuccessInvoice(result.invoiceNumber);
122	    setCart([]);
123	    setPaying(false);
124	    setReceived("");
125	  }
126	
127	  if (successInvoice) {
128	    return (
129	      <div className="flex flex-1 items-center justify-center bg-zinc-50 px-4">
130	        <div className="w-full max-w-sm rounded-2xl border border-zinc-200 bg-white p-6 text-center">
131	          <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-brand-50 text-2xl">
132	            ✅
133	          </div>
134	          <h1 className="text-lg font-bold text-zinc-900">Transaksi berhasil</h1>
135	          <p className="mt-1 text-sm text-zinc-500">No. Struk: {successInvoice}</p>
136	          <button
137	            onClick={() => {
138	              setSuccessInvoice(null);
139	              router.refresh();
140	            }}
141	            className="mt-6 w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700"
142	          >
143	            Transaksi Baru
144	          </button>
145	        </div>
146	      </div>
147	    );
148	  }
149	
150	  return (
151	    <div className="flex flex-1 flex-col overflow-hidden bg-zinc-50 lg:flex-row">
152	      {/* Catalog */}
153	      <div className="flex flex-1 flex-col overflow-hidden">
154	        <div className="flex items-center gap-3 border-b border-zinc-200 bg-white px-4 py-3">
155	          <input
156	            type="text"
157	            value={search}
158	            onChange={(e) => setSearch(e.target.value)}
159	            placeholder="Cari produk…"
160	            className="flex-1 rounded-xl border border-zinc-200 bg-zinc-50 px-3.5 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
161	          />
162	          <div className="text-right">
163	            <p className="text-xs font-semibold text-zinc-700">{cashierName}</p>
164	            <p className="text-[10px] text-zinc-400">{businessName}</p>
165	          </div>
166	        </div>
167	
168	        <div className="flex-1 overflow-y-auto p-4">
169	          {filteredProducts.length === 0 ? (
170	            <p className="mt-10 text-center text-sm text-zinc-400">
171	              {products.length === 0
172	                ? "Belum ada produk. Tambahkan dulu di halaman Kelola Produk."
173	                : "Produk tidak ditemukan."}
174	            </p>
175	          ) : (
176	            <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 xl:grid-cols-4">
177	              {filteredProducts.map((p) => {
178	                const inCart = cart.find((i) => i.productId === p.id)?.qty ?? 0;
179	                const soldOut = p.stock <= 0;
180	                return (
181	                  <button
182	                    key={p.id}
183	                    onClick={() => addToCart(p)}
184	                    disabled={soldOut || inCart >= p.stock}
185	                    className="relative rounded-xl border border-zinc-200 bg-white p-3 text-left transition-colors hover:border-brand-300 disabled:cursor-not-allowed disabled:opacity-50"
186	                  >
187	                    {inCart > 0 && (
188	                      <span className="absolute -right-1.5 -top-1.5 flex h-5 w-5 items-center justify-center rounded-full bg-brand-600 text-[10px] font-bold text-white">
189	                        {inCart}
190	                      </span>
191	                    )}
192	                    <div className="mb-2 flex h-9 w-9 items-center justify-center rounded-lg bg-zinc-100 text-lg">
193	                      {p.emoji || "📦"}
194	                    </div>
195	                    <p className="truncate text-sm font-medium text-zinc-900">{p.name}</p>
196	                    <p className="text-xs text-zinc-500">
197	                      {soldOut ? "Stok habis" : `Stok ${p.stock}`}
198	                    </p>
199	                    <p className="mt-1 text-sm font-semibold text-zinc-900">
200	                      {formatRupiah(p.price)}
201	                    </p>
202	                  </button>
203	                );
204	              })}
205	            </div>
206	          )}
207	        </div>
208	      </div>
209	
210	      {/* Cart */}
211	      <div className="flex w-full flex-col border-t border-zinc-200 bg-white lg:w-80 lg:border-l lg:border-t-0">
212	        <div className="flex-1 overflow-y-auto p-4">
213	          <h2 className="mb-3 text-sm font-semibold text-zinc-900">Keranjang</h2>
214	          {cart.length === 0 ? (
215	            <p className="text-xs text-zinc-400">Belum ada item. Klik produk untuk menambah.</p>
216	          ) : (
217	            <div className="space-y-2">
218	              {cart.map((item) => (
219	                <div key={item.productId} className="rounded-xl border border-zinc-100 p-2.5">
220	                  <div className="flex items-start justify-between gap-2">
221	                    <p className="text-xs font-medium text-zinc-900">{item.name}</p>
222	                    <button
223	                      onClick={() => removeFromCart(item.productId)}
224	                      className="text-xs text-zinc-400 hover:text-red-500"
225	                    >
226	                      ✕
227	                    </button>
228	                  </div>
229	                  <div className="mt-1.5 flex items-center justify-between">
230	                    <div className="flex items-center gap-2">
231	                      <button
232	                        onClick={() => changeQty(item.productId, -1)}
233	                        className="flex h-6 w-6 items-center justify-center rounded-md bg-zinc-100 text-xs font-bold text-zinc-600 hover:bg-zinc-200"
234	                      >
235	                        −
236	                      </button>
237	                      <span className="w-4 text-center text-xs tabular-nums">{item.qty}</span>
238	                      <button
239	                        onClick={() => changeQty(item.productId, 1)}
240	                        disabled={item.qty >= item.maxStock}
241	                        className="flex h-6 w-6 items-center justify-center rounded-md bg-zinc-100 text-xs font-bold text-zinc-600 hover:bg-zinc-200 disabled:opacity-40"
242	                      >
243	                        +
244	                      </button>
245	                    </div>
246	                    <p className="text-xs font-semibold text-zinc-900">
247	                      {formatRupiah(item.price * item.qty)}
248	                    </p>
249	                  </div>
250	                </div>
251	              ))}
252	            </div>
253	          )}
254	        </div>
255	
256	        <div className="border-t border-zinc-200 p-4">
257	          <div className="mb-3 flex items-center justify-between text-sm font-semibold text-zinc-900">
258	            <span>Total</span>
259	            <span>{formatRupiah(subtotal)}</span>
260	          </div>
261	
262	          {!paying ? (
263	            <>
264	              <button
265	                onClick={() => setPaying(true)}
266	                disabled={cart.length === 0}
267	                className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-50"
268	              >
269	                Bayar
270	              </button>
271	              <SwitchCashierButton />
272	            </>
273	          ) : (
274	            <div className="space-y-3">
275	              <div className="grid grid-cols-3 gap-2">
276	                {PAYMENT_METHODS.map((m) => (
277	                  <button
