279	                    onClick={() => setPaymentMethod(m)}
280	                    className={`rounded-xl border py-2 text-xs font-medium transition-colors ${
281	                      paymentMethod === m
282	                        ? "border-brand-600 bg-brand-50 text-brand-700"
283	                        : "border-zinc-200 text-zinc-600 hover:border-zinc-300"
284	                    }`}
285	                  >
286	                    {m}
287	                  </button>
288	                ))}
289	              </div>
290	
291	              {paymentMethod === "Tunai" && (
292	                <div>
293	                  <label htmlFor="received" className="mb-1 block text-xs font-medium text-zinc-600">
294	                    Uang Diterima
